body:
Could technically do what chrome devTool dose in the style inspector
- shift + up += 10
- alt + up += .1
- cmd + up += 100

think this could be a browser implementer choice?

alternative if one wants to implement this on there own:

```js
/**
 * Add DevTools-like stepping to <input type="number"> elements.
 *
 * Usage:
 *   attachModifierStepper(document.querySelector('input[type="number"]'));
 *   // or for many:
 *   document.querySelectorAll('input[type="number"]').forEach(attachModifierStepper);
 */
function attachModifierStepper(input) {
  if (!input || input.tagName !== "INPUT" || input.type !== "number") return;

  input.addEventListener("keydown", (e) => {
    // Only handle ArrowUp / ArrowDown
    if (e.key !== "ArrowUp" && e.key !== "ArrowDown") return;

    // Prevent native stepping so we fully control it
    e.preventDefault();

    const dir = e.key === "ArrowUp" ? 1 : -1;

    // Base step: from step attribute unless it's missing/invalid/"any"
    const stepAttr = input.getAttribute("step");
    let baseStep = Number(stepAttr);

    if (!Number.isFinite(baseStep) || baseStep <= 0) {
      // Reasonable fallback if step="any" or not set
      baseStep = 1;
    }

    // Modifier scaling (DevTools-like)
    let scale = 1;
    if (e.shiftKey) scale *= 10;
    if (e.altKey) scale *= 0.1;
    if (e.metaKey) scale *= 100;

    const delta = dir * baseStep * scale;

    // Current value (treat empty as 0 or min if provided)
    let value = input.value === "" ? NaN : Number(input.value);
    if (!Number.isFinite(value)) {
      const minAttr = input.getAttribute("min");
      const min = Number(minAttr);
      value = Number.isFinite(min) ? min : 0;
    }

    // Apply delta
    let next = value + delta;

    // Respect min/max if present
    const minAttr = input.getAttribute("min");
    const maxAttr = input.getAttribute("max");
    const min = Number(minAttr);
    const max = Number(maxAttr);

    if (Number.isFinite(min)) next = Math.max(min, next);
    if (Number.isFinite(max)) next = Math.min(max, next);

    // Fix floating point noise by rounding to the step's decimal precision
    // (e.g., step=0.1 => 1 decimal place)
    const decimals = (() => {
      const s = String(baseStep);
      const i = s.indexOf(".");
      return i === -1 ? 0 : (s.length - i - 1);
    })();

    if (decimals > 0) {
      const p = 10 ** decimals;
      next = Math.round(next * p) / p;
    } else {
      // Still avoid -0
      if (Object.is(next, -0)) next = 0;
    }

    input.value = String(next);

    // Fire events so frameworks/reactivity notice
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
  });
}
```
